/* @autogenerated */
import { EnvironmentInjector, inject, Injectable } from '@angular/core';
import { HttpEvent, HttpParams, HttpResponse } from '@angular/common/http';
import { map, Observable, of, shareReplay, switchMap, withLatestFrom } from 'rxjs';
import { AppConfigService } from '@shared/context/config/app-config.service';
import { ClientService } from './client.service';
import { AppStateService } from '@shared/context/state/app-state.service';

@Injectable({
  providedIn: 'root',
})
export class ApiService {
  private readonly environmentInjector = inject(EnvironmentInjector);
  private readonly endpointCache = new Map<string, Observable<any>>();

  public constructor(
    private readonly appState: AppStateService,
    private readonly client: ClientService,
    private readonly appConfig: AppConfigService,
  ) {}

  get<T>(endpoint: string, params?: HttpParams): Observable<T> {
    return this.contextualizeParams(this.find(endpoint), params ?? null, (args) => this.client.get(args));
  }

  post<T>(endpoint: string, body: any, params?: HttpParams): Observable<T> {
    return this.contextualizeBody(this.find(endpoint), body, params ?? null, (args) => this.client.post(args));
  }

  download(endpoint: string, params?: HttpParams): Observable<HttpResponse<Blob>> {
    return this.contextualizeParams(this.find(endpoint), params ?? null, (args) => this.client.download(args));
  }

  upload(endpoint: string, name: string, file: File, params?: HttpParams): Observable<HttpEvent<any>> {
    return this.contextualizeParams(this.find(endpoint), params ?? null, (args) =>
      this.client.upload({ name, file, ...args }),
    );
  }

  put<T>(endpoint: string, body: any, params?: HttpParams): Observable<T> {
    return this.contextualizeBody(this.find(endpoint), body, params ?? null, (args) => this.client.put(args));
  }

  patch<T>(endpoint: string, body: any, params?: HttpParams): Observable<T> {
    return this.contextualizeBody(this.find(endpoint), body, params ?? null, (args) => this.client.patch(args));
  }

  delete<T>(endpoint: string, params?: any): Observable<T> {
    return this.contextualizeParams(this.find(endpoint), params ?? null, (args) => this.client.delete(args));
  }

  private contextualizeParams<T>(
    base: Observable<any>,
    params: HttpParams | null,
    merge: (params: any) => Observable<T>,
  ) {
    return this.contextualizeBody(base, null, params, merge);
  }

  private contextualizeBody<T>(
    base: Observable<any>,
    body: any,
    params: HttpParams | null,
    merge: (params: any) => Observable<T>,
  ) {
    const baseParams = params ?? new HttpParams();

    const conf$ = base;
    const fixed$ = body ? this.appState.fixedContext().pipe(shareReplay(1)) : of({});
    return this.appState.filterContext().pipe(
      // Para cada cambio en el filterContext, construimos unos HttpParams nuevos
      withLatestFrom(fixed$),
      switchMap(([aditional, fixed]) => {
        let p = baseParams;
        Object.entries(aditional ?? {}).forEach(([k, v]) => {
          if (v !== undefined && v !== null) {
            const val = v as any;
            p = p.set(k, String(val.$ref ? val.$ref : val)); // HttpParams es inmutable
          }
        });
        const effectiveBody = body ? { ...body } : undefined;
        if (effectiveBody && fixed) {
          Object.entries(fixed ?? {}).forEach(([k, v]) => {
            const val = v as any;
            effectiveBody[k] = val;
          });
        }
        // Combinamos con la config del endpoint
        return conf$.pipe(
          switchMap(
            (conf) =>
              merge(body ? { ...conf, body: effectiveBody, params: p } : { ...conf, params: p }) as Observable<T>,
          ),
        );
      }),
    );
  }

  private find(url: string): Observable<any> {
    const cached = this.endpointCache.get(url);
    if (cached) return cached;

    const obs = this.appConfig['api'].pipe(
      map((apiConf) => {
        let resolvedUrl = url;
        let headers = {} as any;
        let identity = '';
        let sendUid = false;
        if (apiConf) {
          Object.entries(apiConf).forEach(([key, api]: any[]) => {
            let matched = false;
            let prefix = '';
            if (resolvedUrl.startsWith('http://' + key)) {
              prefix = 'http://' + key;
            } else if (resolvedUrl.startsWith('https://' + key)) {
              prefix = 'https://' + key;
            } else if (resolvedUrl.startsWith(key)) {
              prefix = key;
            } else if (resolvedUrl.startsWith(api.url)) {
              prefix = api.url;
            }
            if (prefix.length > 0) {
              matched = true;
            }
            if (matched) {
              if (api.url) {
                resolvedUrl = api.url + resolvedUrl.substring(prefix.length);
              }
              identity = api.identity;
              sendUid = !!api.identity;
              if (api.headers) {
                for (const i of Object.keys(api.headers)) {
                  headers[i] = api.headers[i];
                }
              }
            }
          });
        }
        return { url: resolvedUrl, headers: headers, identity: identity, withIdentity: sendUid };
      }),
      shareReplay({ bufferSize: 1, refCount: false }),
    );

    this.endpointCache.set(url, obs);
    return obs;
  }
}
